"""dictate_norm — 听写文本整形（写进聊天框/输入框前的确定性清洗）

只做一件事：把标点替换成空格，并把连续空白收成一个空格。
开关由 behavior.dictation_punct_to_space 控制（默认关，保持原行为）。
"""
from __future__ import annotations

import re

# 中文标点 + ASCII 标点（不含字母数字、不含中日韩文字）
PUNCT = ("。，、；：？！…—～·「」『』【】（）〔〕《》〈〉“”‘’"
         ",.;:?!\"'()[]{}<>/\\|~_-+*=&#@^`$%")

_RE = re.compile("[" + re.escape(PUNCT) + r"\s\u3000]+")


def punct_to_space(text: str) -> str:
    """标点 → 空格；连续空白合并；去首尾空白。

    例: "你好，世界！测试。" → "你好 世界 测试"
        "A.B  C,"        → "A B C"
    """
    return _RE.sub(" ", text or "").strip()


if __name__ == "__main__":
    for s in ["你好，世界！测试。", "A.B  C,", "补农。。", "「引号」测试；；", "没有标点"]:
        print(repr(s), "→", repr(punct_to_space(s)))
